import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function intOf(value: unknown, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '요청 값이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr03402Controller {
  @Get('/posts/:postId/readers')
  async listPostReaders(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const postId = req.params['postId'];
    if (!/^[0-9]+$/.test(postId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '게시물 번호가 올바르지 않습니다.');
    }
    const page = intOf(query['page'], 0);
    const size = Math.min(Math.max(intOf(query['size'], DEFAULT_SIZE), 1), MAX_SIZE);
    return transaction(async (db) => {
      const posts = await db.query(
        'SELECT visibility_scope AS "visibilityScope" FROM post WHERE post_id = CAST(:postId AS bigint)',
        { postId },
      );
      if (posts.length === 0) {
        throw new ApiError(404, 'POST_NOT_FOUND', '공지·게시물을 찾을 수 없습니다.');
      }
      // 가정: 공개범위 대상 테이블이 없어 전체(ALL)는 재직 임직원 전원, 그 외는 열람 기록이 있는 임직원만 대상으로 본다.
      const isAll = posts[0].visibilityScope === 'ALL' ? 1 : 0;
      const fromWhere =
        ' FROM employee e' +
        ' LEFT JOIN post_read pr ON pr.post_id = CAST(:postId AS bigint) AND pr.employee_id = e.employee_id' +
        ' LEFT JOIN department d ON d.department_id = e.department_id' +
        ' WHERE (CAST(:isAll AS integer) = 1 AND e.employment_status = \'재직\') OR pr.post_read_id IS NOT NULL';
      const totals = await db.query('SELECT COUNT(*) AS "total"' + fromWhere, { postId, isAll });
      const items = await db.query(
        'SELECT e.name AS "readerName", d.name AS "departmentName", pr.read_at AS "readAt",' +
          ' (pr.post_read_id IS NOT NULL) AS "read"' +
          fromWhere +
          ' ORDER BY (pr.post_read_id IS NOT NULL) DESC, pr.read_at, e.name, e.employee_id' +
          ' LIMIT :size OFFSET :offset',
        { postId, isAll, size, offset: page * size },
      );
      return { items, page, size, total: Number(totals[0].total) };
    });
  }
}

