import { useState } from 'react';
import { Band, Badge, DataTable, DateText, ErrorText, Field, Filters, LookupSelect, Pager, Select, Tiles, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr03402Page({ role, notify }: PageProps) {
  const [postId, setPostId] = useState<number | string>('');
  const [view, setView] = useState('');
  const [page, setPage] = useState(0);

  const { data, error, loading } = useData<Page | undefined>(
    async () => {
      if (postId === '') {
        return undefined;
      }
      return call<Page>('GET', `/posts/${postId}/readers`, role, undefined, { page, size: SIZE });
    },
    [postId, page],
  );

  const all: Row[] = data ? data.items : [];
  const rows = all.filter((r) => {
    if (view === 'read') {
      return r.read === true;
    }
    if (view === 'unread') {
      return r.read !== true;
    }
    return true;
  });
  const readCount = all.filter((r) => r.read === true).length;
  const unreadCount = all.length - readCount;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>열람</h2>
        <Tiles items={[['열람자(현재 쪽)', readCount]]} />
      </section>
      <section className="box span-4">
        <h2>미열람</h2>
        <Tiles items={[['미열람자(현재 쪽)', unreadCount]]} />
      </section>
      <section className="box span-4">
        <h2>전체 대상</h2>
        <Tiles items={[['대상 인원', data ? data.total : 0]]} />
      </section>
      <section className="box span-12">
        <h2>열람자 목록</h2>
        <Filters
          onSearch={() => setPage(0)}
          onReset={() => {
            setPostId('');
            setView('');
            setPage(0);
          }}
        >
          <Field label="공지·게시물" required>
            <LookupSelect
              table="post"
              role={role}
              value={postId}
              onChange={(v) => {
                setPostId(v);
                setPage(0);
              }}
              placeholder="공지·게시물 선택"
            />
          </Field>
          <Field label="열람 여부">
            <Select
              value={view}
              onChange={setView}
              options={[['read', '열람'], ['unread', '미열람']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          columns={[
            { key: 'readerName', label: '열람자 이름' },
            { key: 'departmentName', label: '열람자 부서명' },
            { key: 'readAt', label: '열람일시', render: (r) => <DateText value={r.readAt} time /> },
            { key: 'read', label: '열람 여부', render: (r) => <Badge value={r.read === true ? '열람' : '미열람'} /> },
          ]}
          rows={rows}
          empty={postId === '' ? '공지·게시물을 선택하세요.' : loading ? '불러오는 중입니다.' : '열람자가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
    </div>
  );
}
